"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[74479],{3331:(e,t,s)=>{s.d(t,{R:()=>r,x:()=>o});var i=s(36672);const n={},a=i.createContext(n);function r(e){const t=i.useContext(a);return i.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),i.createElement(a.Provider,{value:t},e.children)}},88480:(e,t,s)=>{s.r(t),s.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>c,frontMatter:()=>r,metadata:()=>i,toc:()=>u});const i=JSON.parse('{"id":"2023/03/30","title":"2023-03-30","description":"Homog\xe9n\xe9isation de la conception : Avantages et inconv\xe9nients","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/2023/03/30.md","sourceDirName":"2023/03","slug":"/2023/03/30","permalink":"/fr/2023/03/30","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/fr/docusaurus-plugin-content-docs//current/2023/03/30.md","tags":[],"version":"current","frontMatter":{"localized_date":"30 mars 2023","top_news":"Homog\xe9n\xe9isation de la conception : Avantages et inconv\xe9nients"},"sidebar":"defaultSidebar","previous":{"title":"31","permalink":"/fr/2023/03/31"},"next":{"title":"2023-03-29","permalink":"/fr/2023/03/29"}}');var n=s(23420),a=s(3331);const r={localized_date:"30 mars 2023",top_news:"Homog\xe9n\xe9isation de la conception : Avantages et inconv\xe9nients"},o="2023-03-30",l={},u=[{value:"Homog\xe9n\xe9isation de la conception : Avantages et inconv\xe9nients",id:"homog\xe9n\xe9isation-de-la-conception--avantages-et-inconv\xe9nients",level:2},{value:"Les difficult\xe9s de Binance et le d\xe9bat sur la l\xe9gitimit\xe9 de la crypto-monnaie",id:"les-difficult\xe9s-de-binance-et-le-d\xe9bat-sur-la-l\xe9gitimit\xe9-de-la-crypto-monnaie",level:2},{value:"Picsart AI lance l&#39;outil Text2video-Zero pour les vid\xe9os synth\xe9tiques",id:"picsart-ai-lance-loutil-text2video-zero-pour-les-vid\xe9os-synth\xe9tiques",level:2},{value:"Ubuntu abandonne Flatpak pour Snap : La communaut\xe9 Linux r\xe9agit",id:"ubuntu-abandonne-flatpak-pour-snap--la-communaut\xe9-linux-r\xe9agit",level:2},{value:"L&#39;\xe9tui Cooler Master transforme un ordinateur portable Framework en un ordinateur de bureau \xe0 39 dollars",id:"l\xe9tui-cooler-master-transforme-un-ordinateur-portable-framework-en-un-ordinateur-de-bureau-\xe0-39-dollars",level:2},{value:"Disney ferme le Metaverse au milieu des critiques et du scepticisme",id:"disney-ferme-le-metaverse-au-milieu-des-critiques-et-du-scepticisme",level:2},{value:"La d\xe9fense de Sam Bankman-Fried financ\xe9e par l&#39;argent du don",id:"la-d\xe9fense-de-sam-bankman-fried-financ\xe9e-par-largent-du-don",level:2},{value:"Utilisation de ChatGPT pour la productivit\xe9 dans le d\xe9veloppement de logiciels",id:"utilisation-de-chatgpt-pour-la-productivit\xe9-dans-le-d\xe9veloppement-de-logiciels",level:2},{value:"Les bizarreries des langages de programmation : le ph\xe9nom\xe8ne &#39;Wat&#39;.",id:"les-bizarreries-des-langages-de-programmation--le-ph\xe9nom\xe8ne-wat",level:2},{value:"Google a commis une &quot;destruction de preuves&quot; et a menti, selon un juge am\xe9ricain",id:"google-a-commis-une-destruction-de-preuves-et-a-menti-selon-un-juge-am\xe9ricain",level:2}];function d(e){const t={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"2023-03-30",children:"2023-03-30"})}),"\n",(0,n.jsx)(t.h2,{id:"homog\xe9n\xe9isation-de-la-conception--avantages-et-inconv\xe9nients",children:"Homog\xe9n\xe9isation de la conception : Avantages et inconv\xe9nients"}),"\n",(0,n.jsxs)(t.p,{children:["L'article traite de la tendance \xe0 l'homog\xe9n\xe9isation du design et de l'esth\xe9tique, en soulignant ses avantages et ses inconv\xe9nients. La convergence du design est due aux pr\xe9f\xe9rences des clients et des fabricants et est \xe9vidente dans divers secteurs, notamment la construction automobile, l'architecture et l'image de marque. La discussion soul\xe8ve des questions sur l'\xe9quilibre entre l'optimisation et la cr\xe9ativit\xe9 dans le domaine du design et des affaires, et sur les limites potentielles de l'homog\xe9n\xe9isation \xe0 l'innovation et \xe0 l'individualit\xe9. L'article remet en question l'id\xe9e que les gens du monde entier veulent les m\xeames choses et affirme que la concr\xe9tisation des d\xe9sirs diff\xe8re d'une culture \xe0 l'autre. L'effet moodboard a conduit au blanding, mais il existe une opportunit\xe9 pour les marques et les entreprises audacieuses et originales de se d\xe9marquer.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35355703",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(t.a,{href:"https://www.alexmurrell.co.uk/articles/the-age-of-average",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"les-difficult\xe9s-de-binance-et-le-d\xe9bat-sur-la-l\xe9gitimit\xe9-de-la-crypto-monnaie",children:"Les difficult\xe9s de Binance et le d\xe9bat sur la l\xe9gitimit\xe9 de la crypto-monnaie"}),"\n",(0,n.jsxs)(t.p,{children:["Binance est aux prises avec des sorties de fonds de 2 milliards de dollars, des interdictions r\xe9glementaires et des critiques sur ses pratiques douteuses. Pendant ce temps, le d\xe9bat sur la l\xe9gitimit\xe9 des crypto-monnaies et des NFT se poursuit, avec des critiques de certains \xe9changes et projets pour des signaux d'alarme tels que des titres non enregistr\xe9s et un manque de conformit\xe9 avec les r\xe9glementations. La discussion porte \xe9galement sur les arguments pour et contre la r\xe9glementation des crypto-monnaies et sur les risques potentiels associ\xe9s \xe0 l'investissement dans ces derni\xe8res. La CFTC am\xe9ricaine a r\xe9cemment intent\xe9 un proc\xe8s \xe0 Binance, l'accusant d'op\xe9rer ill\xe9galement aux \xc9tats-Unis et de violer les r\xe8gles de n\xe9gociation. Malgr\xe9 les inqui\xe9tudes, le jeton BNB de Binance n'a pas \xe9t\xe9 affect\xe9, alors que l'industrie dans son ensemble fait l'objet d'une surveillance r\xe9glementaire accrue.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35351805",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(t.a,{href:"https://www.wsj.com/articles/binance-sees-2-billion-in-outflows-as-troubles-compound-9a136e21",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"picsart-ai-lance-loutil-text2video-zero-pour-les-vid\xe9os-synth\xe9tiques",children:"Picsart AI lance l'outil Text2video-Zero pour les vid\xe9os synth\xe9tiques"}),"\n",(0,n.jsxs)(t.p,{children:["Picsart AI Research a publi\xe9 Text2Video-Zero, un outil qui g\xe9n\xe8re des vid\xe9os synth\xe9tiques \xe0 partir d'un texte d'entr\xe9e en utilisant le traitement du langage naturel. Le code et les poids du mod\xe8le sont disponibles, ce qui permet aux particuliers d'ex\xe9cuter leur propre instance du logiciel sur un syst\xe8me dot\xe9 d'au moins 12 Go de VRAM. Cette publication a suscit\xe9 l'int\xe9r\xeat de la communaut\xe9 de l'IA g\xe9n\xe9rative, malgr\xe9 certains commentaires sarcastiques. Cependant, l'IA a des limites dans la cr\xe9ation d'\u0153uvres d'art qui r\xe9pondent aux besoins et aux \xe9motions des \xeatres humains, et les mod\xe8les d'IA ne peuvent pas remplacer la vision cr\xe9ative et artistique des artistes VFX humains. L'outil Text-to-Video with Edge Guidance g\xe9n\xe8re des vid\xe9os \xe0 partir de textes, y compris de diff\xe9rents styles, et est disponible sur GitHub sous la licence CreativeML Open RAIL-M.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35352452",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(t.a,{href:"https://github.com/Picsart-AI-Research/Text2Video-Zero",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"ubuntu-abandonne-flatpak-pour-snap--la-communaut\xe9-linux-r\xe9agit",children:"Ubuntu abandonne Flatpak pour Snap : La communaut\xe9 Linux r\xe9agit"}),"\n",(0,n.jsxs)(t.p,{children:["Canonical a mis fin au support de Flatpak et propose d\xe9sormais exclusivement Snap, ce qui a provoqu\xe9 une controverse parmi les utilisateurs de Linux qui critiquent la lenteur des m\xe9canismes de mise \xe0 jour et les limitations de Snaps. Les utilisateurs se sont tourn\xe9s vers d'autres distributions telles que Fedora et Linux Mint ou ont recommand\xe9 des images Debian non libres et PopOS \xe0 d'autres pour r\xe9soudre les probl\xe8mes de pilotes. La conversation met en \xe9vidence l'importance du contr\xf4le et du choix de l'utilisateur, la question de savoir si ce sont les d\xe9veloppeurs d'applications ou les distributions qui doivent empaqueter les logiciels, et la n\xe9cessit\xe9 de formats d'empaquetage normalis\xe9s. Certains utilisateurs pr\xe9f\xe8rent Flatpak \xe0 Snap et s'inqui\xe8tent de la d\xe9cision de Canonical, tandis que d'autres voient la valeur des deux syst\xe8mes pour les anciennes versions des distributions Linux.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35354729",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(t.a,{href:"https://lwn.net/SubscriberLink/927262/6adb2350e2b0d2ce/",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"l\xe9tui-cooler-master-transforme-un-ordinateur-portable-framework-en-un-ordinateur-de-bureau-\xe0-39-dollars",children:"L'\xe9tui Cooler Master transforme un ordinateur portable Framework en un ordinateur de bureau \xe0 39 dollars"}),"\n",(0,n.jsxs)(t.p,{children:["Cooler Master propose un bo\xeetier \xe0 39 $ qui transforme un vieil ordinateur portable Framework en un PC de bureau, avec un stockage extensible et une alimentation ATX standard. Les utilisateurs de Hacker News approuvent l'id\xe9e de r\xe9utiliser les pi\xe8ces d'un vieil ordinateur portable, mais discutent \xe9galement de la r\xe9utilisation et de la r\xe9duction des d\xe9chets \xe9lectroniques. Framework vise \xe0 faire \xe9conomiser de l'argent aux consommateurs gr\xe2ce \xe0 des unit\xe9s centrales et des options de stockage extensibles et \xe0 r\xe9duire les d\xe9chets \xe9lectroniques. L'entreprise lance \xe9galement un PC de bureau \xe0 monter soi-m\xeame, au prix de 999 dollars, qui se veut une plateforme modulaire, peu gourmande en \xe9nergie et personnalisable. Framework Laptop, un ordinateur portable open-source, r\xe9parable et \xe9volutif, est lanc\xe9 comme une alternative durable et abordable aux fabricants traditionnels de PC. Framework s'associe \xe0 Cooler Master pour le bo\xeetier transparent \xe0 39 $ et lance un bo\xeetier de batterie de d\xe9monstration et un bloc-batterie \xe0 plus haute densit\xe9 pour ses ordinateurs portables.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35350288",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(t.a,{href:"https://www.theverge.com/2023/3/23/23652939/framework-cooler-master-sff-pc-case",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"disney-ferme-le-metaverse-au-milieu-des-critiques-et-du-scepticisme",children:"Disney ferme le Metaverse au milieu des critiques et du scepticisme"}),"\n",(0,n.jsxs)(t.p,{children:["Disney a ferm\xe9 sa division Metaverse, ce qui a donn\xe9 lieu \xe0 des sp\xe9culations selon lesquelles le projet \xe9tait trop risqu\xe9. Les d\xe9tracteurs de la r\xe9alit\xe9 virtuelle (RV) \xe9voquent le mal des transports, le co\xfbt \xe9lev\xe9 des casques et l'isolement social. Certains affirment que les limites et les inconv\xe9nients de la RV en font un concept peu judicieux. Le succ\xe8s des parcs \xe0 th\xe8me repose sur des liens \xe9motionnels qui ne peuvent \xeatre reproduits par des exp\xe9riences de RV. La fermeture de la division Metaverse a suscit\xe9 des discussions sur l'avenir de la RV et le potentiel de la technologie de la r\xe9alit\xe9 augment\xe9e (RA). L'id\xe9e du Metaverse a \xe9t\xe9 critiqu\xe9e parce qu'elle n'\xe9tait qu'un simple train \xe0 vapeur. La d\xe9cision de Disney de fermer la division sugg\xe8re qu'elle a peut-\xeatre revu \xe0 la baisse ses attentes quant \xe0 la croissance du Metaverse. Les commentateurs s'interrogent sur l'avenir de la RV pour le g\xe9ant des m\xe9dias et du divertissement.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35350952",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(t.a,{href:"https://www.wsj.com/articles/disney-eliminates-its-metaverse-division-as-part-of-companys-layoffs-plan-94b03650",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"la-d\xe9fense-de-sam-bankman-fried-financ\xe9e-par-largent-du-don",children:"La d\xe9fense de Sam Bankman-Fried financ\xe9e par l'argent du don"}),"\n",(0,n.jsxs)(t.p,{children:["Le fondateur de FTX, Sam Bankman-Fried, financerait sa d\xe9fense en justice avec l'argent qu'il a donn\xe9 \xe0 son p\xe8re, ce qui, selon certains commentaires sur Hacker News, aurait \xe9t\xe9 r\xe9alis\xe9 gr\xe2ce \xe0 des astuces comptables pour \xe9viter les imp\xf4ts. Les avocats ont la responsabilit\xe9 professionnelle de s'assurer qu'ils agissent de mani\xe8re \xe9thique et qu'ils v\xe9rifient l'origine des fonds qui leur sont vers\xe9s, compte tenu du risque de r\xe9cup\xe9ration, le gouvernement pouvant l\xe9galement pr\xe9tendre que les fonds proviennent du produit d'un crime. Certains commentateurs de l'article s'interrogent sur la l\xe9galit\xe9 de la caution de 250 millions de dollars garantie par Bankman-Fried, ainsi que sur le risque de saisie des actifs en cas d'activit\xe9 criminelle. D'autres discutent de l'\xe9thique des professionnels et critiquent les frais \xe9lev\xe9s factur\xe9s par les syndics de faillite dans les cas de r\xe9cup\xe9ration.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35358698",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(t.a,{href:"https://www.forbes.com/sites/sarahemerson/2023/03/29/sam-bankman-fried-legal-fees-funded-by-alameda-money-gifted-to-father-joe-bankman/",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"utilisation-de-chatgpt-pour-la-productivit\xe9-dans-le-d\xe9veloppement-de-logiciels",children:"Utilisation de ChatGPT pour la productivit\xe9 dans le d\xe9veloppement de logiciels"}),"\n",(0,n.jsxs)(t.p,{children:["L'utilisation de ChatGPT d'OpenAI est de plus en plus r\xe9pandue dans le d\xe9veloppement de logiciels, ce qui permet d'augmenter consid\xe9rablement la productivit\xe9, en particulier pour les d\xe9veloppeurs chevronn\xe9s. Cependant, elle ne remplacera pas les codeurs de sit\xf4t, car la cr\xe9ativit\xe9, les comp\xe9tences en mati\xe8re de r\xe9solution de probl\xe8mes et la capacit\xe9 \xe0 bien travailler au sein d'une \xe9quipe restent essentielles. Investir dans l'auto-automatisation et la cr\xe9ation d'outils peut faire de quelqu'un un ing\xe9nieur tr\xe8s productif et pr\xe9cieux. L'article fournit des exemples pratiques d'utilisation de la technologie de l'IA pour am\xe9liorer la productivit\xe9 dans le d\xe9veloppement de logiciels. Les commentaires de certains programmeurs exp\xe9riment\xe9s r\xe9v\xe8lent des inqui\xe9tudes quant aux inconv\xe9nients potentiels des outils d'IA, tels que la maintenabilit\xe9, le d\xe9bogage et l'impact sur les emplois dans le domaine du g\xe9nie logiciel. L'efficacit\xe9 du concept de programmeur 10x, la qualit\xe9 de l'enseignement de l'informatique et le processus d'embauche dans l'industrie technologique sont \xe9galement abord\xe9s dans les commentaires.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35356054",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(t.a,{href:"https://kadekillary.work/posts/1000x-eng/",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"les-bizarreries-des-langages-de-programmation--le-ph\xe9nom\xe8ne-wat",children:"Les bizarreries des langages de programmation : le ph\xe9nom\xe8ne 'Wat'."}),"\n",(0,n.jsxs)(t.p,{children:["L'article met en \xe9vidence le ph\xe9nom\xe8ne \"WAT\" dans les langages de programmation, o\xf9 des bizarreries dans le comportement peuvent \xeatre d\xe9routantes ou inattendues. Il fait r\xe9f\xe9rence \xe0 un article de Hacker News et \xe0 un fil de discussion Reddit sur des comportements \xe9tranges en JavaScript et en Python, respectivement. La discussion refl\xe8te l'\xe9volution constante des langages de programmation et l'importance du contexte, de la coh\xe9rence et de la lisibilit\xe9. L'article traite \xe9galement d'une vid\xe9o de Gary Bernhardt intitul\xe9e \"WAT\", qui pr\xe9sente certaines des bizarreries de JavaScript. De nombreux commentateurs admirent la vid\xe9o pour son approche cr\xe9ative, tout en reconnaissant les bizarreries du langage.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35363044",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(t.a,{href:"https://www.destroyallsoftware.com/talks/wat",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"google-a-commis-une-destruction-de-preuves-et-a-menti-selon-un-juge-am\xe9ricain",children:'Google a commis une "destruction de preuves" et a menti, selon un juge am\xe9ricain'}),"\n",(0,n.jsxs)(t.p,{children:["Un juge f\xe9d\xe9ral am\xe9ricain a estim\xe9 que Google avait d\xe9truit des preuves et menti au tribunal, une conclusion lourde de cons\xe9quences pour les litiges en mati\xe8re d'ententes et d'abus de position dominante. Le juge a estim\xe9 que les employ\xe9s de Google discutaient r\xe9guli\xe8rement de sujets commerciaux importants, ce qui peut conduire \xe0 une d\xe9duction d\xe9favorable indiquant que les preuves supprim\xe9es \xe9taient en d\xe9faveur de Google. Cette d\xe9cision concerne les poursuites engag\xe9es par Epic Games et le minist\xe8re de la justice. Le juge n'a pas encore sanctionn\xe9 Google, mais des amendes seront impos\xe9es lorsque l'enqu\xeate sur les faits sera termin\xe9e. Les entreprises sont responsables des actes de leurs employ\xe9s, et les personnes responsables de la destruction de preuves doivent \xeatre tenues pour responsables. Les commentateurs sugg\xe8rent d'\xe9chelonner les amendes en fonction du chiffre d'affaires de l'entreprise, \xe0 l'instar des amendes impos\xe9es par les banques pour lutter contre le blanchiment d'argent et le terrorisme.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35363095",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(t.a,{href:"https://storage.courtlistener.com/recap/gov.uscourts.cand.373179/gov.uscourts.cand.373179.469.0.pdf",children:"Lire le texte original"}),"."]})]})}function c(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}}}]);